async function publicWorkbookQuoteRoute(request, env, actor) {
  if (env.EXCEL_RFQ_ENABLED !== "true") return null;
  const match = new URL(request.url).pathname.match(/^\/api\/vendor\/rfq-workbooks\/([^/]+)\/quote$/);
  if (!match || request.method !== "POST") return null;
  if (!actor || actor.role !== "vendor" || actor.status !== "active") return fail("VENDOR_REQUIRED", 403);
  const accepted = await acceptanceFor(env, actor);
  if (!accepted) return fail("TERMS_ACCEPTANCE_REQUIRED", 403);
  const vendor = await env.DB.prepare("SELECT * FROM vendors WHERE user_id=? AND verification_status='verified'").bind(actor.id).first();
  if (!vendor) return fail("VENDOR_VERIFICATION_REQUIRED", 403);
  const book = await env.DB.prepare("SELECT * FROM rfq_workbook_revisions WHERE id=? AND parent_kind='public' AND status='published'").bind(match[1]).first();
  if (!book) return fail("PUBLIC_RFQ_NOT_AVAILABLE", 404);
  const c2 = JSON.parse(book.content_json);
  if (Date.parse(c2.quoteDeadline) <= Date.now()) return fail("RFQ_CLOSED", 409);
  const parent = await parentFor(env, "public", book.parent_id);
  if (!parent || parent.status !== "dispatched_to_vendors") return fail("RFQ_NOT_AVAILABLE", 404);
  let parsed, response;
  try {
    const body = await rfqJson(request, 15000000);
    parsed = decodeDocument(body.excelFile);
    if (!parsed.type.includes("spreadsheetml")) throw Error("MATCHING_XLSX_REQUIRED");
    response = readRfqWorkbook(parsed.bytes, c2);
    if (response.totalAmountAed <= 0) throw Error("POSITIVE_QUOTATION_REQUIRED");
  } catch (e2) {
    return fail(e2 instanceof Error ? e2.message : "INVALID_WORKBOOK");
  }
  const id = crypto.randomUUID(), key = "private/workbook-responses/" + id + ".xlsx", now = (/* @__PURE__ */ new Date()).toISOString();
  await env.DOCUMENTS_BUCKET.put(key, parsed.bytes, { httpMetadata: { contentType: parsed.type } });
  try {
    const result = await env.DB.batch([
      env.DB.prepare("UPDATE rfq_workbook_responses SET superseded_at=? WHERE workbook_id=? AND vendor_id=? AND quotation_id IS NULL AND superseded_at IS NULL AND EXISTS(SELECT 1 FROM rfq_workbook_revisions w JOIN get_a_quote_requests r ON r.id=w.parent_id WHERE w.id=? AND w.status='published' AND r.status='dispatched_to_vendors')").bind(now, book.id, vendor.id, book.id),
      env.DB.prepare("INSERT INTO rfq_workbook_responses(id,workbook_id,vendor_id,original_r2_key,original_sha256,prices_json,response_json,total_amount_aed,created_at) VALUES (?,(SELECT w.id FROM rfq_workbook_revisions w WHERE w.id=? AND w.status='published' AND EXISTS(SELECT 1 FROM get_a_quote_requests r WHERE r.id=w.parent_id AND r.status='dispatched_to_vendors') AND EXISTS(SELECT 1 FROM vendors v JOIN users u ON u.id=v.user_id WHERE v.id=? AND v.verification_status='verified' AND u.status='active') AND json_extract(w.content_json,'$.quoteDeadline')>? AND EXISTS(SELECT 1 FROM terms_acceptance_evidence e JOIN terms_versions t ON t.id=e.terms_version_id WHERE e.acceptance_id=? AND e.acceptance_status='accepted' AND NOT EXISTS(SELECT 1 FROM terms_versions n WHERE n.role='vendor' AND n.mandatory=1 AND n.status IN ('published','retired') AND n.published_at>t.published_at))),?,?,?,?,?,?,?)").bind(id, book.id, vendor.id, now, accepted.acceptance_id, vendor.id, key, await digest2(parsed.bytes), JSON.stringify(response.rates), JSON.stringify(response), response.totalAmountAed, now), env.DB.prepare("INSERT INTO audit_logs(id,actor_user_id,actor_role,action_type,resource_type,resource_id,payload_json,timestamp) SELECT ?,?,'vendor','PUBLIC_RFQ_WORKBOOK_QUOTATION','rfq_workbook_response',id,?,? FROM rfq_workbook_responses WHERE id=?").bind(crypto.randomUUID(), actor.id, JSON.stringify({ revision: book.revision }), now, id)]);
    if (!result[1].meta.changes) throw Error("WORKBOOK_REVISION_CONFLICT");
    return ok({ id, totalAmountAed: response.totalAmountAed, rfqRevision: book.revision }, 201);
  } catch {
    await env.DOCUMENTS_BUCKET.delete(key);
    return fail("QUOTATION_CONFLICT", 409);
  }
}
async function publicWorkbookListings(env, actor) {
  if (env.EXCEL_RFQ_ENABLED !== "true") return [];
  const profile = await organizationFor(env, actor), vendor = await env.DB.prepare("SELECT trade_categories FROM vendors WHERE id=? AND verification_status='verified'").bind(profile?.id ?? "").first();
  if (!vendor) return [];
  const rows = await env.DB.prepare("SELECT w.id,w.parent_id,w.revision,w.content_json,r.reference_code,r.location_emirate,r.work_category,r.created_at FROM rfq_workbook_revisions w JOIN get_a_quote_requests r ON r.id=w.parent_id WHERE w.parent_kind='public' AND w.status='published' AND r.status='dispatched_to_vendors'").all();
  return rows.results.flatMap((row) => {
    const c2 = JSON.parse(row.content_json);
    if (Date.parse(c2.quoteDeadline) <= Date.now()) return [];
    return [{ id: row.parent_id, referenceCode: row.reference_code, title: c2.title, category: c2.category, projectName: row.reference_code, locationEmirate: c2.emirate, submissionDeadline: c2.quoteDeadline, scopeDescription: c2.summary, contractorDisplayName: "Client #" + row.reference_code, status: "reviewed_published", procurementType: "standard", createdAt: row.created_at, items: [], documents: [], excelOnly: true, excelWorkbook: { id: row.id, revision: row.revision, parentKind: "public", preliminary: c2.preliminary } }];
  });
}
// RFQ-only extensions to the recovered, verified production baseline.
async function rfqJson(request, limit) {
  if (Number(request.headers.get("Content-Length") || 0) > limit) throw Error("REQUEST_TOO_LARGE");
  const reader = request.body?.getReader();
  if (!reader) throw Error("INVALID_REQUEST");
  let size = 0;
  const decoder = new TextDecoder(), chunks = [];
  for (;;) {
    const { value, done } = await reader.read();
    if (done) break;
    size += value.byteLength;
    if (size > limit) { await reader.cancel(); throw Error("REQUEST_TOO_LARGE"); }
    chunks.push(decoder.decode(value, { stream: true }));
  }
  chunks.push(decoder.decode());
  const body = JSON.parse(chunks.join(""));
  if (!body || typeof body !== "object" || Array.isArray(body)) throw Error("INVALID_REQUEST");
  return body;
}

async function reviewedSourceEvidence(env, document) {
  const original = await env.DOCUMENTS_BUCKET.get(document.r2_object_key);
  const derivative = await env.DOCUMENTS_BUCKET.get(document.standardized_r2_key);
  if (!original || !derivative) throw Error("SOURCE_DOCUMENT_UNAVAILABLE");
  if (await sha(new Uint8Array(await original.arrayBuffer())) !== document.sha256_hash || await sha(new Uint8Array(await derivative.arrayBuffer())) !== document.standardized_sha256) throw Error("SOURCE_DOCUMENT_INTEGRITY_FAILED");
}

async function workbookResponseDto(env, row, actor) {
  const book = await env.DB.prepare("SELECT * FROM rfq_workbook_revisions WHERE id=?").bind(row.workbook_id).first();
  const content = JSON.parse(book.content_json), submitted = JSON.parse(row.response_json);
  const current = await publishedWorkbook(env, book.parent_kind, book.parent_id);
  const own = actor.role === "vendor", identity = !own && actor.role !== "admin" ? await env.DB.prepare("SELECT v.company_name,v.contact_person,v.contact_phone,v.trade_license_number,u.email FROM vendors v JOIN users u ON u.id=v.user_id WHERE v.id=?").bind(row.vendor_id).first() : {};
  const clean = (value) => !own && actor.role !== "admin" ? maskedText(value, identity ?? {}) : value;
  return {
    id: row.id, quotationId: row.quotation_id, parentKind: book.parent_kind, parentId: book.parent_id,
    referenceCode: content.reference, revision: book.revision, currentRevision: current?.revision ?? null,
    staleRevision: !current || current.id !== book.id, preliminary: content.preliminary,
    vendorDisplayName: "Vendor #" + row.vendor_id.slice(0, 8), totalAmountAed: row.total_amount_aed,
    leadTimeDays: submitted.leadTimeDays, validityDays: submitted.validityDays, paymentTerms: clean(submitted.paymentTerms),
    notes: clean(submitted.notes), submittedAt: row.created_at,
    status: row.deleted_at ? "removed" : row.withdrawn_at ? "withdrawn" : row.superseded_at ? "superseded" : "submitted",
    items: content.rows.map((item, index) => ({ ...item, unitRateAed: submitted.rates[index].unitRate, totalPriceAed: submitted.rates[index].amount, remarks: clean(submitted.rates[index].remarks || "") }))
  };
}

async function quoteWorkbookData(env, quote, forVendor) {
  const response = await env.DB.prepare("SELECT * FROM rfq_workbook_responses WHERE quotation_id=? ORDER BY created_at DESC,rowid DESC LIMIT 1").bind(quote.id).first();
  if (!response) return {};
  return { workbookResponse: await workbookResponseDto(env, response, { role: forVendor ? "vendor" : "contractor" }) };
}

async function rfqExtensionsRoute(request, env, actor) {
  if (env.EXCEL_RFQ_ENABLED !== "true") return null;
  const url = new URL(request.url), path = url.pathname;
  const repost = path.match(/^\/api\/admin\/rfqs\/([^/]+)\/repost$/);
  if (repost && request.method === "POST") {
    if (actor?.role !== "admin" || actor.status !== "active") return fail("ADMIN_REQUIRED", 403);
    try {
      const body = await rfqJson(request, 20000);
      if (!/^[a-zA-Z0-9_-]{8,80}$/.test(body.requestKey ?? "")) throw Error("REPOST_REQUEST_KEY_REQUIRED");
      const source = await env.DB.prepare("SELECT * FROM rfqs WHERE id=? AND deleted_at IS NULL AND status='cancelled'").bind(repost[1]).first();
      if (!source || await env.DB.prepare("SELECT id FROM awards WHERE rfq_id=?").bind(source.id).first()) throw Error("CANCELLED_UNAWARDED_RFQ_REQUIRED");
      const existing = await env.DB.prepare("SELECT id FROM rfqs WHERE contractor_id=? AND creation_key=?").bind(source.contractor_id, "repost:" + body.requestKey).first();
      if (existing) return ok({ id: existing.id, sourceId: source.id, reused: true });
      if (!Array.isArray(body.sourceDocumentIds) || !body.sourceDocumentIds.length || body.sourceDocumentIds.length > 5 || new Set(body.sourceDocumentIds).size !== body.sourceDocumentIds.length) throw Error("REVIEWED_SOURCE_DOCUMENTS_REQUIRED");
      const documents = [];
      for (const id of body.sourceDocumentIds) {
        const document = await env.DB.prepare("SELECT * FROM rfq_documents WHERE id=? AND rfq_id=? AND quotation_id IS NULL AND standardization_status='approved' AND standardized_r2_key IS NOT NULL").bind(id, source.id).first();
        if (!document) throw Error("REVIEWED_SOURCE_DOCUMENTS_REQUIRED");
        if (!await env.DB.prepare("SELECT id FROM audit_logs WHERE actor_user_id=? AND resource_id=? AND action_type='DOCUMENT_ACCESS'").bind(actor.id, id).first() || !await env.DB.prepare("SELECT id FROM audit_logs WHERE actor_user_id=? AND resource_id=? AND action_type='STANDARD_DOCUMENT_ACCESS'").bind(actor.id, id).first()) throw Error("OPEN_SOURCE_AND_DERIVATIVE_BEFORE_REPOST");
        await reviewedSourceEvidence(env, document);
        documents.push(document);
      }
      const deadline = body.submissionDeadline || source.submission_deadline;
      if (!Number.isFinite(Date.parse(deadline)) || Date.parse(deadline) <= Date.now()) throw Error("FUTURE_QUOTATION_DEADLINE_REQUIRED");
      const id = crypto.randomUUID(), now = new Date().toISOString(), reference = "RFQ-" + crypto.randomUUID();
      const guard = "EXISTS(SELECT 1 FROM rfqs WHERE id=? AND status='cancelled' AND deleted_at IS NULL AND NOT EXISTS(SELECT 1 FROM awards WHERE rfq_id=rfqs.id))";
      const statements = [env.DB.prepare(`INSERT INTO rfqs(id,reference_code,contractor_id,title,category,project_name,location_emirate,submission_deadline,target_completion_date,scope_description,estimated_budget_aed,status,created_at,procurement_type,approved_manpower_quantity,manpower_persons,manpower_hours_per_person_per_day,manpower_days,creation_key) SELECT ?,?,?,?,?,?,?,?,?,?,?,'submitted',?,?,?,?,?,?,? WHERE ${guard}`).bind(id, reference, source.contractor_id, source.title, source.category, source.project_name, source.location_emirate, new Date(deadline).toISOString(), source.target_completion_date, source.scope_description, source.estimated_budget_aed, now, source.procurement_type, source.approved_manpower_quantity, source.manpower_persons, source.manpower_hours_per_person_per_day, source.manpower_days, "repost:" + body.requestKey, source.id)];
      statements.push(env.DB.prepare("INSERT INTO rfq_items(id,rfq_id,item_number,description,quantity,unit,specifications) SELECT lower(hex(randomblob(16))),?,item_number,description,quantity,unit,specifications FROM rfq_items WHERE rfq_id=? AND EXISTS(SELECT 1 FROM rfqs WHERE id=?)").bind(id, source.id, id));
      for (const doc of documents) statements.push(env.DB.prepare("INSERT INTO rfq_documents(id,rfq_id,uploader_user_id,file_name,file_type,file_size_bytes,r2_object_key,document_purpose,sha256_hash,created_at,vendor_access_approved,standardization_status,standardized_content_json,standardized_r2_key,standardized_file_type,standardized_size_bytes,standardized_sha256,standardized_at) SELECT ?,?,uploader_user_id,file_name,file_type,file_size_bytes,r2_object_key,document_purpose,sha256_hash,?,vendor_access_approved,standardization_status,standardized_content_json,standardized_r2_key,standardized_file_type,standardized_size_bytes,standardized_sha256,standardized_at FROM rfq_documents WHERE id=? AND standardization_status='approved' AND EXISTS(SELECT 1 FROM rfqs WHERE id=?)").bind(crypto.randomUUID(), id, now, doc.id, id));
      statements.push(env.DB.prepare("INSERT INTO audit_logs(id,actor_user_id,actor_role,action_type,resource_type,resource_id,payload_json,timestamp) SELECT ?,?,'admin','RFQ_REPOST_PREPARED','rfq',id,?,? FROM rfqs WHERE id=?").bind(crypto.randomUUID(), actor.id, JSON.stringify({ sourceId: source.id, sourceDocumentIds: body.sourceDocumentIds, exclusions: body.exclusions ?? [], originalPreserved: true }), now, id));
      const result = await env.DB.batch(statements);
      if (!result[0].meta.changes) throw Error("REPOST_CONFLICT");
      return ok({ id, referenceCode: reference, sourceId: source.id, status: "submitted" }, 201);
    } catch (error) { return fail(error instanceof Error ? error.message : "REPOST_FAILED", 409); }
  }
  if (path === "/api/admin/rfq-workbook-responses" && request.method === "GET") {
    if (actor?.role !== "admin" || actor.status !== "active") return fail("ADMIN_REQUIRED", 403);
    const kind = url.searchParams.get("parentKind"), id = url.searchParams.get("parentId");
    if (!["public", "contractor"].includes(kind) || !id) return fail("RFQ_REFERENCE_REQUIRED");
    const rows = await env.DB.prepare("SELECT s.* FROM rfq_workbook_responses s JOIN rfq_workbook_revisions w ON w.id=s.workbook_id WHERE w.parent_kind=? AND w.parent_id=? ORDER BY s.created_at DESC LIMIT 100").bind(kind, id).all();
    return ok(await Promise.all(rows.results.map(row => workbookResponseDto(env, row, actor))));
  }
  if (path === "/api/vendor/my-quotes" && request.method === "GET") {
    if (actor?.role !== "vendor" || !await acceptanceFor(env, actor)) return fail("VENDOR_REQUIRED", 403);
    const vendor = await env.DB.prepare("SELECT * FROM vendors WHERE user_id=? AND verification_status='verified'").bind(actor.id).first();
    if (!vendor) return fail("VENDOR_VERIFICATION_REQUIRED", 403);
    const quotes = await env.DB.prepare("SELECT * FROM vendor_quotes WHERE deleted_at IS NULL AND vendor_id=?").bind(vendor.id).all();
    const data = [];
    for (const quote of quotes.results) {
      const parent = await env.DB.prepare("SELECT * FROM rfqs WHERE id=?").bind(quote.rfq_id).first();
      data.push({ ...await quoteDto(env, quote, true), rfq: parent ? await rfqDto(env, parent, true) : null });
    }
    const responses = await env.DB.prepare("SELECT s.*,w.content_json,w.parent_id FROM rfq_workbook_responses s JOIN rfq_workbook_revisions w ON w.id=s.workbook_id WHERE s.vendor_id=? AND s.quotation_id IS NULL AND s.superseded_at IS NULL AND s.deleted_at IS NULL ORDER BY s.created_at DESC").bind(vendor.id).all();
    for (const row of responses.results) {
      const response = await workbookResponseDto(env, row, actor), content = JSON.parse(row.content_json);
      data.push({ ...response, referenceCode: "QTE-" + row.id, rfqId: row.parent_id, pricingMode: "file", documents: [], items: [], workbookResponse: response, withdrawnAt: row.withdrawn_at, rfq: { id: row.parent_id, referenceCode: content.reference, title: content.title, category: content.category, locationEmirate: content.emirate, submissionDeadline: content.quoteDeadline, scopeDescription: content.scope, status: "reviewed_published", items: [], documents: [], procurementType: "standard", excelOnly: true, excelWorkbook: { id: row.workbook_id, revision: content.revision, parentKind: "public", preliminary: content.preliminary } } });
    }
    return ok(data);
  }
  const withdraw = path.match(/^\/api\/vendor\/quotations\/([^/]+)\/(recall|remove)$/);
  if (withdraw && request.method === "POST") {
    if (actor?.role !== "vendor" || !await acceptanceFor(env, actor)) return fail("VENDOR_REQUIRED", 403);
    const vendor = await env.DB.prepare("SELECT id FROM vendors WHERE user_id=? AND verification_status='verified'").bind(actor.id).first();
    const row = await env.DB.prepare("SELECT id FROM rfq_workbook_responses WHERE id=? AND quotation_id IS NULL").bind(withdraw[1]).first();
    if (!row) return null;
    const now = new Date().toISOString();
    const result = await env.DB.batch([env.DB.prepare("UPDATE rfq_workbook_responses SET withdrawn_at=coalesce(withdrawn_at,?),deleted_at=? WHERE id=? AND vendor_id=? AND superseded_at IS NULL AND deleted_at IS NULL AND EXISTS(SELECT 1 FROM rfq_workbook_revisions w JOIN get_a_quote_requests r ON r.id=w.parent_id WHERE w.id=workbook_id AND r.status='dispatched_to_vendors')").bind(now, withdraw[2] === "remove" ? now : null, row.id, vendor?.id ?? ""), env.DB.prepare("INSERT INTO audit_logs(id,actor_user_id,actor_role,action_type,resource_type,resource_id,payload_json,timestamp) SELECT ?,?,'vendor',?,'rfq_workbook_response',id,'{}',? FROM rfq_workbook_responses WHERE id=? AND vendor_id=? AND withdrawn_at=?").bind(crypto.randomUUID(), actor.id, withdraw[2] === "remove" ? "PUBLIC_QUOTATION_REMOVE" : "PUBLIC_QUOTATION_RECALL", now, row.id, vendor?.id ?? "", now)]);
    return result[0].meta.changes ? ok({ id: row.id, withdrawn: true, removed: withdraw[2] === "remove" }) : fail("QUOTATION_NOT_WITHDRAWABLE", 409);
  }
  return null;
}

// urbanprocures advanced/workers/isolation.ts
function isIsolatedAdvancedRequest(request, environment, platformDomain) {
  if (environment === "advanced-production") {
    const url = new URL(request.url);
    return platformDomain === "urbanprocures.com" && url.protocol === "https:" && [
      "urbanprocures.com",
      "www.urbanprocures.com",
      "urbanprocures-advanced-production-20261007.abdeenniyas23.workers.dev"
    ].includes(url.hostname.toLowerCase());
  }
  if (!["advanced-development", "advanced-staging"].includes(environment) || typeof platformDomain !== "string" || !platformDomain.trim()) return false;
  const isProductionHost = (host) => {
    const normalized = host.toLowerCase().replace(/\.$/, "");
    return normalized === "urbanprocures.com" || normalized.endsWith(".urbanprocures.com");
  };
  let configuredHost;
  try {
    configuredHost = new URL(platformDomain.includes("://") ? platformDomain : `https://${platformDomain}`).hostname;
  } catch {
    return false;
  }
  return !isProductionHost(new URL(request.url).hostname) && !isProductionHost(configuredHost);
}

